import glom
import glom.specs as glom_specs
from glom.specs import Auto, Fill, Iter, Let, ROOT
class Invoke:
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs
    def __repr__(self):
        return f'Invoke({self.func.__name__}, {self.args}, {self.kwargs})'
class Fill(glom_specs.Specifier):
    def __init__(self, expr, value):
        self.expr = expr
        self.value = value
    def __repr__(self):
        return f'Fill({self.expr}, {self.value})'
class Assign:
    def __repr__(self):
        return 'Assign()'
class Coalesce:
    def __repr__(self):
        return 'Coalesce()'
class Inspect:
    def __repr__(self):
        return 'Inspect()'
